// ============================================
// VALIDATION INPUT - RAG Delete Source
// ============================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const errors = [];

// --- Required fields ---
const action = body.action;
const sourceId = body.source_id;
const tenantId = body.tenant_id || headers['x-tenant-id'] || headers['X-Tenant-ID'];
const guildId = body.guild_id;
const botId = body.bot_id;

// Backend API config (optional for delete confirmation)
const backendApiUrl = body.backend_api_url || null;
const backendServiceToken = body.backend_service_token || null;

// B2 file key (for logging/tracing)
const b2FileKey = body.b2_file_key || null;

// Validate required
if (!action) errors.push('action requis');
else if (action !== 'delete') errors.push('action doit etre delete');

if (!sourceId) errors.push('source_id requis');
if (!tenantId) errors.push('tenant_id requis');
if (!guildId) errors.push('guild_id requis');
if (!botId) errors.push('bot_id requis');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    source_id: sourceId
  };
}

return {
  valid: true,
  action: action,
  source_id: sourceId,
  tenant_id: tenantId,
  guild_id: guildId,
  bot_id: botId,
  b2_file_key: b2FileKey,
  backend_api_url: backendApiUrl,
  backend_service_token: backendServiceToken,
  start_time: Date.now()
};

// ============================================
// DELETE FROM QDRANT
// Delete all points where source_id matches
// ============================================

const ctx = $input.first().json;

// In real implementation:
// 1. Connect to Qdrant
// 2. Delete points with filter: { source_id: ctx.source_id }
// 3. Collection: rag_sources or tenant-specific

// Qdrant delete by filter payload:
// POST /collections/{collection}/points/delete
// {
//   "filter": {
//     "must": [
//       { "key": "source_id", "match": { "value": "src_xxx" } }
//     ]
//   }
// }

// Simulate deletion
const deletedCount = 0; // Would be actual count from Qdrant response

return {
  ...ctx,
  qdrant_deleted: true,
  deleted_count: deletedCount,
  qdrant_collection: 'rag_sources'
};

